const { parse } = require('./packages/babel-parser/lib/index.js');
const shouldFail = [
  // await/yield actually inside parameter initializers
  [`function f(a = await b) {}`, 'script'],
  [`function* g(a = yield b) {}`, 'script'],
  [`(a = await b) => {}`, 'script'],
  [`async (a = yield b) => {}`, 'script'],
  [`function f({a = await b}) {}`, 'script'],
  // await in async fn params
  [`async function f(a = await b) {}`, 'script'],
];
for (const [code, type] of shouldFail) {
  try {
    parse(code, { sourceType: type });
    console.log('MISSING ERROR:', JSON.stringify(code));
  } catch (e) {
    console.log('fails as expected:', JSON.stringify(code), '->', e.message.split('\n')[0]);
  }
}
const shouldPass = [
  [`(async function () { function f(_=()=>null) {} await null; });`, 'script'],
  [`(function* () { function f(_=()=>null) {} yield; });`, 'script'],
  [`(async function () { function f(_=(a)=>null) {} await null; });`, 'script'],
  [`(async function () { function f(_=()=>{return null;}) {} await null; });`, 'script'],
  [`(async function () { var g = ()=>null; await null; });`, 'script'],
  [`function f(_=()=>null) {}`, 'script'],
  [`async () => await x`, 'module'],
  [`async function f() { await null; }`, 'script'],
  [`(async function () { function f(_=()=>null, __=()=>2) {} await null; });`, 'script'],
  [`(async function () { function f([a]=()=>null ? [] : []) {} await null; });`, 'script'],
  [`x = function f(_ = () => async function () { await 1 }) {};`, 'script'],
  [`function* g() { function f(_=()=>null) {} yield 1; }`, 'script'],
  [`(async function () { class C { m(_=()=>null) {} } await null; });`, 'script'],
  [`(async function () { function f(_ = async () => { await 1; }) {} await null; });`, 'script'],
  [`let f = _ => _; async function g() { await f(); }`, 'module'],
  // nested arrow chains with concise bodies
  [`(async function () { function f(_ = () => () => null) {} await null; });`, 'script'],
  // await inside nested arrow concise body within default param of outer arrow head
  [`async (a = () => await x) => {}`, 'module'],
];
for (const [code, type] of shouldPass) {
  try {
    parse(code, { sourceType: type, allowAwaitOutsideFunction: false, errorRecovery: false });
    console.log('parses:', JSON.stringify(code.slice(0, 60)));
  } catch (e) {
    console.log('UNEXPECTED FAIL:', JSON.stringify(code.slice(0, 60)), '->', e.message.split('\n')[0]);
  }
}

